CREATE TABLE IF NOT EXISTS "public"."polls" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "tenant_id" "text" DEFAULT ''::"text" NOT NULL,
    "title" "text" NOT NULL,
    "single_choice" boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS "public"."poll_options" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "tenant_id" "text" DEFAULT ''::"text" NOT NULL,
    "description" "text" NOT NULL,
    "poll_id" bigint,
    "vote_count" bigint NOT NULL DEFAULT 0
);

ALTER TABLE ONLY "public"."poll_options"
    ADD CONSTRAINT "poll_option_of_fkey" FOREIGN KEY ("poll_id") REFERENCES "public"."polls"("id") ON UPDATE CASCADE ON DELETE SET NULL;

CREATE TABLE IF NOT EXISTS "public"."poll_votes" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "tenant_id" "text" DEFAULT ''::"text" NOT NULL,
    "poll_option_id" bigint,
    "profile_id" bigint
);

ALTER TABLE ONLY "public"."poll_votes"
    ADD CONSTRAINT "vote_for_fkey" FOREIGN KEY ("poll_option_id") REFERENCES "public"."poll_options"("id") ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE ONLY "public"."poll_votes"
    ADD CONSTRAINT "voted_by_fkey" FOREIGN KEY ("profile_id") REFERENCES "public"."profiles"("id") ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE ONLY "public"."news"
    ADD CONSTRAINT "news_poll_fkey" FOREIGN KEY ("poll") REFERENCES "public"."polls"("id") ON UPDATE CASCADE ON DELETE SET NULL;

CREATE UNIQUE INDEX "poll_vote_unique"
    ON "public"."poll_votes"(profile_id, poll_option_id);

CREATE INDEX IF NOT EXISTS "poll_options_poll_id_idx"
    ON "public"."poll_options"(poll_id);

CREATE POLICY "tenant_isolation" ON "public"."polls" USING (("tenant_id" = ((SELECT current_setting('request.headers'::"text", true))::"json" ->> 'x-tenant-id'::"text")));
CREATE POLICY "tenant_isolation" ON "public"."poll_options" USING (("tenant_id" = ((SELECT current_setting('request.headers'::"text", true))::"json" ->> 'x-tenant-id'::"text")));
CREATE POLICY "tenant_isolation" ON "public"."poll_votes" USING (("tenant_id" = ((SELECT current_setting('request.headers'::"text", true))::"json" ->> 'x-tenant-id'::"text")));

CREATE OR REPLACE FUNCTION update_vote_count()
    RETURNS TRIGGER AS $$
    BEGIN
        IF TG_OP = 'INSERT' THEN
            UPDATE poll_options SET vote_count = vote_count + 1 WHERE id = NEW.poll_option_id;
        ELSE
            UPDATE poll_options SET vote_count = vote_count - 1 WHERE id = OLD.poll_option_id;
        END IF;

        RETURN COALESCE(NEW, OLD);
    END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE TRIGGER "update_vote_count" AFTER INSERT OR DELETE ON "public"."poll_votes" FOR EACH ROW EXECUTE FUNCTION "public"."update_vote_count"();

CREATE INDEX IF NOT EXISTS "poll_options_poll_id_idx" ON "public"."poll_options"(poll_id);
CREATE INDEX IF NOT EXISTS "poll_votes_profile_idx" ON "public"."poll_votes"(profile_id);
CREATE INDEX IF NOT EXISTS "poll_votes_option_idx" ON "public"."poll_votes"(poll_option_id);


CREATE OR REPLACE FUNCTION "public"."get_poll_with_permissions"(
    p_poll_id bigint,
    p_profile_id bigint DEFAULT NULL,
    p_is_admin boolean DEFAULT false
)
    RETURNS json
    LANGUAGE plpgsql
    AS $$
    DECLARE
        result json;
        v_has_voted boolean := false;
    BEGIN

        -- 1. Check if user has voted in this poll
        IF p_profile_id IS NOT NULL THEN
            SELECT EXISTS (
                SELECT 1
                FROM poll_votes v
                         JOIN poll_options o ON o.id = v.poll_option_id
                WHERE v.profile_id = p_profile_id
                  AND o.poll_id = p_poll_id
            )
            INTO v_has_voted;
        END IF;

        -- 2. Build result
        SELECT json_build_object(
                       'id', p.id,
                       'title', p.title,
                       'singleChoice', p.single_choice,
                       'hasVoted', COALESCE(v_has_voted, false),

                       'options',
                       (
                           SELECT json_agg(
                                          json_build_object(
                                                  'id', o.id,
                                                  'description', o.description,
                                                  'voteCount',
                                                  CASE
                                                      WHEN p_is_admin OR v_has_voted THEN o.vote_count
                                                  END,
                                                  'wasVotedByUser',
                                                  EXISTS (
                                                      SELECT 1
                                                      FROM poll_votes v
                                                      WHERE v.poll_option_id = o.id
                                                        AND v.profile_id = p_profile_id
                                                  )
                                          )
                                  )
                           FROM poll_options o
                           WHERE o.poll_id = p.id
                       )

               )
        INTO result
        FROM polls p
        WHERE p.id = p_poll_id;

        RETURN result;
    END;
$$;

CREATE OR REPLACE FUNCTION "public"."cast_poll_vote"(
    p_poll_id bigint,
    p_option_ids bigint[],
    p_profile_id bigint,
    p_tenant_id text
)
    RETURNS void
    LANGUAGE plpgsql
    AS $$
    DECLARE
        v_single_choice boolean;
    BEGIN
        PERFORM pg_advisory_xact_lock(hashtextextended(format('poll_vote:%s:%s', p_poll_id, p_profile_id), 0));

        SELECT single_choice INTO v_single_choice FROM polls WHERE id = p_poll_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Poll not found';
        END IF;

        IF cardinality(p_option_ids) = 0 OR (v_single_choice AND cardinality(p_option_ids) > 1) THEN
            RAISE EXCEPTION 'Invalid number of options';
        END IF;

        IF (SELECT COUNT(*) FROM poll_options WHERE id = ANY(p_option_ids) AND poll_id = p_poll_id) <> cardinality(p_option_ids) THEN
            RAISE EXCEPTION 'One or more options do not belong to this poll';
        END IF;

        IF EXISTS (
            SELECT 1
            FROM poll_votes v
                     JOIN poll_options o ON o.id = v.poll_option_id
            WHERE v.profile_id = p_profile_id
              AND o.poll_id = p_poll_id
        ) THEN
            RAISE EXCEPTION 'This user already voted for this poll';
        END IF;

        INSERT INTO poll_votes (poll_option_id, profile_id, tenant_id)
        SELECT unnest(p_option_ids), p_profile_id, p_tenant_id;
    END;
$$;

-- RLS STUFF

ALTER TABLE polls ENABLE ROW LEVEL SECURITY;
ALTER TABLE poll_options ENABLE ROW LEVEL SECURITY;
ALTER TABLE poll_votes ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION is_poll_admin()
    RETURNS boolean
    LANGUAGE sql
    STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM profiles p
        WHERE p.auth_id = auth.uid()
          AND (
            'admin' = ANY(p.roles)
                OR 'editor' = ANY(p.roles)
            )
    );
$$;


